// ============================================================
// B-計算漲跌幅並篩選新警報
// 用途：確認證交所即時報價正常、今天有開盤，再組成「大盤指數速報」。
// 輸出三種結果：
//   ・今天有開盤 → { marketOpen: true, message: 速報文字 }
//   ・今天沒開盤，且是 09 點這一輪 → { marketOpen: false, dataDate: 報價的資料日期 }
//   ・其他情況 → 回傳空清單 []，流程在這裡結束、不推播
// ============================================================

// 證交所即時報價 API：tse_t00 = 加權指數，otc_o00 = 櫃買指數
const twseUrl = 'https://mis.twse.com.tw/stock/api/getStockInfo.jsp?ex_ch=tse_t00.tw|otc_o00.tw&json=1&delay=0';
// sleep(毫秒)：讓程式暫停一段時間。JS 沒有內建 sleep，這是常見的自訂寫法
function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

// $('節點名稱').first().json：讀取指定節點輸出的第一筆資料
// 語法：let 宣告「之後會改變」的變數；const 宣告「不會再改變」的常數
let quoteResp = $('B-查詢即時報價').first().json;
// msgArray 是各指數的報價清單；「|| []」表示這個欄位不存在時，就當成空清單
let msgArray = quoteResp.msgArray || [];

// 【檢查 1】API 偶爾會回傳空資料：每次等 2 秒後重新查詢，最多重試 2 次
let retries = 0;
while (msgArray.length === 0 && retries < 2) {   // while：條件成立就一直重複；&& 表示「而且」
  await sleep(2000);                             // await：等這個動作完成再往下執行
  try {
    // this.helpers.httpRequest：在 Code 節點裡直接發出 HTTP 請求
    quoteResp = await this.helpers.httpRequest({ url: twseUrl, json: true });
  } catch (e) {
    // try...catch：請求出錯時不讓程式中斷，改成當作空資料，繼續下一輪重試
    quoteResp = {};
  }
  msgArray = quoteResp.msgArray || [];
  retries++;                                     // retries++ 等於 retries = retries + 1
}

// 重試後仍然是空的：主動丟出錯誤（throw），讓執行紀錄顯示失敗，而不是默默略過
if (msgArray.length === 0) {
  throw new Error('台股即時報價API連續回傳空資料，已重試' + retries + '次仍失敗，本次跳過推播');
}

// 取得台北時間的「今天」，格式化成 yyyyLLdd（例如 20260929；LL 是兩位數月份）
const tpNow = $now.setZone('Asia/Taipei');
const todayStr = tpNow.toFormat('yyyyLLdd');

// 【檢查 2】證交所伺服器日期（sysDate）不是今天 → API 本身異常，中止
// 「A && B」：A 存在才去讀 B，避免讀取不存在的欄位時出錯
const sysDate = String((quoteResp.queryTime && quoteResp.queryTime.sysDate) || '');
if (sysDate && sysDate !== todayStr) {           // !== 表示「不等於」
  throw new Error(`證交所API伺服器日期(${sysDate})與今日(${todayStr})不符，疑似API異常，本次跳過推播`);
}

// 【檢查 3】讀取報價的資料日期（欄位 d）；沒有這個欄位就無法判斷有沒有開盤，中止
const dataDate = String(msgArray[0].d || '');    // msgArray[0]：清單的第一筆（從 0 開始算）
if (!dataDate) {                                 // ! 表示「沒有／不成立」
  throw new Error('台股即時報價缺少資料日期欄位(d)，無法確認今日是否開盤，本次跳過推播');
}

// 【檢查 4】資料日期不是今天 → 報價還停在上一個交易日 → 今天沒開盤
//   ・09 點這一輪：交給後面的節點判斷是「預定休市」還是「颱風等非預定休市」
//   ・其他時段：直接結束（同一天只需要判斷一次，避免重複通知）
if (dataDate !== todayStr) {
  if (tpNow.hour === 9) return [{ json: { marketOpen: false, dataDate } }];
  return [];
}

// 【正常開盤】逐一計算每個指數的漲跌點數與漲跌幅
const now = $now.setZone('Asia/Taipei').toFormat('HH:mm');   // 目前時間，例如 10:30，放在訊息標題
const lines = [];                                             // 用來收集每一行訊息的清單
for (const s of msgArray) {                                   // for...of：逐一取出清單中的每一筆
  // z = 最新成交價，沒有的話依序改用 pz、b；parseFloat 把文字轉成數字
  const z = parseFloat(s.z || s.pz || s.b || '0');
  // y = 昨日收盤價
  const y = parseFloat(s.y || '0');
  if (!y || !z) continue;                                     // 缺少任一價格就跳過（continue = 直接處理下一筆）
  const diff = z - y;                                         // 漲跌點數
  const pct = (diff / y) * 100;                               // 漲跌幅（%）
  // 「條件 ? A : B」：條件成立取 A，否則取 B。這裡依漲、跌、平盤選擇箭頭
  const arrow = diff > 0 ? '▲' : diff < 0 ? '▼' : '─';
  // 反引號 `...${變數}...` 是「樣板字串」，可以把變數直接嵌進文字
  // toFixed(2)：取到小數第 2 位；Math.abs：取絕對值（去掉負號）
  lines.push(`${s.n} ${z.toFixed(2)} ${arrow}${Math.abs(diff).toFixed(2)} (${pct > 0 ? '+' : ''}${pct.toFixed(2)}%)`);
}

// API 有回應卻算不出任何指數：資料格式可能改變了，主動報錯
if (lines.length === 0) {
  throw new Error('台股即時報價API有回應但無有效指數資料');
}

// 組成速報訊息：lines.join('\n') 用換行把每一行接起來
const message = `📊 大盤指數速報 ${now}\n\n${lines.join('\n')}`;
// 回傳給下一個節點；n8n 規定的格式是 [{ json: { ...資料... } }]
return [{ json: { marketOpen: true, message } }];

// ============================================================
// C-組合台股訊息
// 用途：把 AI 挑選的結果組成最終推播訊息。
// 重點設計：
//   ・新聞連結依 AI 回傳的「編號」從候選清單取回，完全不採用 AI 寫的網址（防止捏造）
//   ・今天是平日休市 → 訊息最上方加休市通知；特殊交易日 → 加上提示
//   ・AI 失敗 → 改推保底訊息，讓使用者知道系統有在運作
// ============================================================

// 取回前面節點的資料：交易日狀態、候選新聞清單
const st = $('C-取得交易日狀態').first().json || {};
const cand = $('C-整理候選新聞').first().json || {};
// 建立「編號 → 新聞」的對照表，之後可以用編號快速查到標題與連結
const byId = new Map((cand.candidates || []).map(c => [c.id, c]));

// 摘要節點失敗時 onError 會繼續往下走，這裡容許各種輸出形狀
const j = $input.first().json || {};
// AI 的結果通常放在 output 欄位；沒有的話就把整筆資料當作結果
let out = j.output !== undefined ? j.output : j;
// 如果結果是文字（不是物件），就移除 ``` 程式碼區塊符號後嘗試解析成 JSON；解析失敗就當作沒有結果
if (typeof out === 'string') { try { out = JSON.parse(out.replace(/```(json)?/g, '')); } catch (e) { out = null; } }
// 有效的結果：必須是物件，而且至少有 taiwan 或 us 其中一個清單
const valid = out && typeof out === 'object' && (Array.isArray(out.taiwan) || Array.isArray(out.us));

// 記錄已經用過的新聞編號，避免同一則新聞同時出現在台股與美股
const used = new Set();
// clean：移除摘要裡的 Markdown 符號（LINE 不會顯示成格式），並整理多餘空白
const clean = s => String(s || '').replace(/[*#`>\[\]]/g, '').replace(/\s+/g, ' ').trim();
// 連結依編號從候選清單取回，不採用 AI 寫出的網址
// section：把 AI 回傳的一個清單（台股或美股）轉成「1. 摘要 / 🔗 連結」的文字
function section(list) {
  const lines = [];
  let n = 0;                                               // 已經加入幾則
  for (const it of Array.isArray(list) ? list : []) {      // list 不是清單時就當成空清單
    const c = byId.get(Number(it && it.id));               // 依編號查出原始新聞；查不到代表 AI 編了不存在的編號
    const summary = clean(it && it.summary);
    if (!c || !summary || used.has(c.id)) continue;        // 查不到、沒有摘要、已經用過 → 跳過
    used.add(c.id);
    n++;
    lines.push(`${n}. ${summary}`, `🔗 ${c.link}`);        // 連結來自候選清單，不是 AI
    if (n >= 3) break;                                     // 每區最多 3 則
  }
  return lines.length ? lines.join('\n') : '今日無符合條件的重點新聞';
}

// parts：訊息的各個段落，最後用空行接起來
const parts = [];
// 平日休市（不是交易日，而且不是週末）→ 最上方加休市通知
if (st.isTradingDay === false && !st.isWeekend) {
  parts.push([
    `🔕 台股今日 ${st.dateLabel}休市`,
    `原因：${st.closedReason}`,
    '今日不推播盤中速報與成交量排行',
    `下次開盤：${st.nextTradingLabel}`
  ].join('\n'));
}
// 特殊交易日（開紅盤、封關日）→ 加上提示
if (st.specialNote) parts.push(`🎯 ${st.specialNote}`);

// 標題：固定文字＋加權指數收盤行情；filter(Boolean) 會拿掉空字串，避免多出空行
const title = ['📊 台股+美股財經速報', cand.indexBrief || ''].filter(Boolean).join('\n');
if (valid) {
  // AI 結果有效：組成台股、美股兩區
  parts.push([title, '━━━━━━━━━━', '📈 台股', section(out.taiwan), '━━━━━━━━━━', '🌍 美股', section(out.us)].join('\n'));
} else {
  // AI 失敗：推保底訊息
  parts.push(`${title}\n⚠️ 今日新聞摘要生成失敗，請稍後至財經網站查看`);
}

// 各段落之間空一行（'\n\n'），交給 LINE 推播節點
return [{ json: { finalMessage: parts.join('\n\n') } }];

// ============================================================
// D-整理成交量排行前20
// 用途：把證交所「成交量前 20 名」的原始資料整理成易讀的訊息。
// 休市判斷：證交所 API 本身就是最準的答案。今天沒交易時 stat 不會是 'OK'，
//          這裡就回傳空清單 [] 不推播，連颱風假也自動涵蓋。
// ============================================================

// 上一個節點（證交所 API）的回應
const resp = $input.first().json;
// 三種情況都不推播：stat 不是 OK、沒有 data 欄位、data 是空的（|| 表示「或」）
if (resp.stat !== 'OK' || !resp.data || !resp.data.length) {
  return [];
}

// slice(0, 20)：只取前 20 筆
const rows = resp.data.slice(0, 20);
// map：把清單的每一筆轉換成新的樣子，這裡是轉成一行文字
// 「r => { ... }」是箭頭函式，r 代表目前處理的那一筆
const lines = rows.map(r => {
  // 每一筆是陣列：[排名, 證券代號, 證券名稱, 成交股數, ...]
  const rank = r[0], code = r[1], name = r[2], volumeRaw = r[3];
  // 成交股數是含千分位逗號的文字（例如 "12,345,678"）：先移除逗號再轉成整數
  // replace(/,/g, '')：/,/g 是正規表示式，g 表示「全部」逗號都換掉
  const shares = parseInt(String(volumeRaw).replace(/,/g, ''), 10);
  // 股數 ÷ 1000 = 張數，Math.round 四捨五入
  const lots = Math.round(shares / 1000);
  // toLocaleString()：把數字加上千分位逗號，例如 12346 → 12,346
  return `${rank}. ${name}(${code}) 量:${lots.toLocaleString()}張`;
});

// 組成訊息標題與內容（resp.date 是證交所回傳的資料日期）
let message = `📊 今日成交量排行前20名（${resp.date}）\n\n${lines.join('\n')}`;
// 從交易日狀態子流程取得休市預告：明天開始連假時，附加在訊息最後（+= 表示接在後面）
const st = $('D-取得交易日狀態').first().json || {};
if (st.breakNotice) message += `\n\n${st.breakNotice}`;
return [{ json: { message } }];

// ============================================================
// C-整理候選新聞
// 用途：把 4 個 RSS 來源的新聞整理成「編號候選清單」交給 AI 挑選，
//       並從前一交易日收盤資料算出「行情背景」。
// 輸出：
//   ・newsList：給 AI 看的文字清單，格式 [編號] (來源) 標題
//   ・candidates：完整清單（含連結），之後「C-組合台股訊息」會依編號取回連結
//   ・marketContext / indexBrief：加權、櫃買指數的收盤行情文字
// ============================================================

const TZ = 'Asia/Taipei';
// 網域 → 來源中文名稱的對照表（{ 鍵: 值 } 是 JS 的「物件」，類似 Python 的 dict）
const SOURCE = { 'ec.ltn.com.tw': '自由時報', 'news.ltn.com.tw': '自由時報', 'money.udn.com': '經濟日報', 'www.cnbc.com': 'CNBC', 'www.marketwatch.com': 'MarketWatch' };
// 每個來源最多取幾則
const PER_SOURCE = 10;
// 24 小時前的時間點（毫秒數）；比這個時間更早的新聞不要
const cutoffMs = $now.minus({ hours: 24 }).toMillis();

// 只取最近24小時，每個來源各取最新10則，避免單一來源洗版
// Map 是「鍵 → 值」的對照容器，這裡用「網域 → 該來源的新聞清單」分組
const groups = new Map();
// $input.all()：Merge 節點傳進來的所有新聞；{ json: n } 是把每筆的 json 欄位取出來命名為 n
for (const { json: n } of $input.all()) {
  if (!n || !n.title || !n.link) continue;               // 沒有標題或連結就跳過
  // Date.parse：把發布時間文字轉成毫秒數；解析失敗或太舊就跳過
  const t = Date.parse(n.isoDate || n.pubDate || '');
  if (!t || t < cutoffMs) continue;
  // 用正規表示式從連結取出網域，例如 https://money.udn.com/... → money.udn.com
  const m = String(n.link).match(/^https?:\/\/([^\/?#]+)/i);
  if (!m) continue;
  const host = m[1].toLowerCase();                        // m[1] 是括號裡抓到的部分；toLowerCase 轉小寫
  if (!groups.has(host)) groups.set(host, []);            // 第一次看到這個網域就建立空清單
  // 標題裡連續的空白、換行統一換成一個空格；trim 去掉前後空白
  groups.get(host).push({ title: String(n.title).replace(/\s+/g, ' ').trim(), link: n.link, t, source: SOURCE[host] || host });
}

// 依來源逐一挑選，並給每則新聞一個流水編號
const candidates = [];
for (const list of groups.values()) {
  list.sort((a, b) => b.t - a.t);                         // 依時間由新到舊排序
  const seen = new Set();                                 // Set：不重複的集合，用來記錄看過的標題
  for (const n of list) {
    if (seen.has(n.title)) continue;                      // 同一來源的重複標題跳過
    seen.add(n.title);
    candidates.push({ id: candidates.length + 1, source: n.source, title: n.title, link: n.link });
    if (seen.size >= PER_SOURCE) break;                   // 這個來源已取滿 10 則，換下一個來源（break = 跳出迴圈）
  }
}

// 從「C-取得昨日收盤」計算前一交易日的收盤行情
const parts = [];
try {
  for (const s of $('C-取得昨日收盤').first().json.msgArray || []) {
    const z = parseFloat(s.z || s.pz || '0');             // 收盤價
    const y = parseFloat(s.y || '0');                     // 前一日收盤價
    if (!z || !y) continue;
    const diff = z - y;                                   // 漲跌點數
    const pct = (diff / y) * 100;                         // 漲跌幅（%）
    const arrow = diff > 0 ? '▲' : diff < 0 ? '▼' : '─';
    // 資料日期 20260924 → 「9/24 」；Number('09') 會變成 9，去掉前面的 0
    const d = String(s.d || '');
    const dLabel = d.length === 8 ? `${Number(d.slice(4, 6))}/${Number(d.slice(6, 8))} ` : '';
    // 證交所的正式名稱太長，改成「加權指數」
    const name = s.n === '發行量加權股價指數' ? '加權指數' : s.n;
    // 加上千分位並固定 2 位小數，例如 48024.6 → 48,024.60
    const price = z.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    parts.push(`${name} ${dLabel}收盤 ${price} ${arrow}${Math.abs(diff).toFixed(2)}（${pct > 0 ? '+' : ''}${pct.toFixed(2)}%）`);
  }
} catch (e) {}
// ↑ 收盤資料取得失敗時什麼都不做，只是少了行情背景，不影響新聞推播

return [{
  json: {
    // 給 AI 看的清單：每則一行，例如「[12] (經濟日報) 台股季底作帳最後衝刺」
    newsList: candidates.map(c => `[${c.id}] (${c.source}) ${c.title}`).join('\n'),
    candidates,                                           // 完整清單（含連結）
    candidateCount: candidates.length,                    // 候選新聞數量，方便除錯
    marketContext: parts.join('\n'),                      // 完整行情背景（加權＋櫃買），放進 AI 提示詞
    indexBrief: parts[0] || ''                            // 只取第一行（加權指數），放在推播訊息標題下
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "taiwan": {
      "type": "array",
      "description": "台股相關重點新聞，依重要性排序，最多3則",
      "maxItems": 3,
      "items": {
        "type": "object",
        "properties": {
          "id": { "type": "integer", "description": "候選新聞編號" },
          "summary": { "type": "string", "description": "一句話繁體中文摘要，40字以內" }
        },
        "required": ["id", "summary"]
      }
    },
    "us": {
      "type": "array",
      "description": "美股與國際市場重點新聞，依重要性排序，最多3則",
      "maxItems": 3,
      "items": {
        "type": "object",
        "properties": {
          "id": { "type": "integer", "description": "候選新聞編號" },
          "summary": { "type": "string", "description": "一句話繁體中文摘要，40字以內" }
        },
        "required": ["id", "summary"]
      }
    }
  },
  "required": ["taiwan", "us"]
}

