// ============================================================
// B-判斷非預定休市
// 用途：09:30 發現報價沒更新（今天沒開盤）時，判斷要不要發休市通知。
//   ・預定休市（國定假日等，證交所清單查得到）→ 08:00 已通知過，不重複推播
//   ・非預定休市（颱風假等，清單查不到）→ 推播「今日未開盤」通知
//   ・休市日資料查詢失敗 → 仍推播通知，但註明「原因無法確認」
// ============================================================

// 上一個節點（交易日狀態子流程）的結果；「|| {}」表示沒有資料時當成空物件
const st = $input.first().json || {};
// 從「B-計算漲跌幅並篩選新警報」取回報價的資料日期，例如 20260924
const dataDate = String($('B-計算漲跌幅並篩選新警報').first().json.dataDate || '');

// 預定休市（證交所清單內）08:00 已通知，這裡不重複推播
// st.ok = 休市日資料查詢成功；isTradingDay === false = 今天不是交易日（=== 表示「完全等於」）
if (st.ok && st.isTradingDay === false) return [];

// 把 20260924 轉成 2026/09/24 方便閱讀；slice(開始, 結束) 取出文字的一段
// 資料日期長度不是 8 碼時，改用「上一個交易日」這幾個字
const last = dataDate.length === 8 ? `${dataDate.slice(0, 4)}/${dataDate.slice(4, 6)}/${dataDate.slice(6, 8)}` : '上一個交易日';
// 依休市日資料是否查詢成功，決定要寫哪一種原因
const reason = st.ok ? '非預定休市（可能因颱風等因素）' : '休市原因無法確認（證交所休市日資料暫時無法取得）';

// 組成通知訊息：把清單裡的每一行用換行（'\n'）接起來
return [{
  json: {
    message: [
      `⚠️ 台股今日 ${st.dateLabel || ''}未開盤`,
      reason,
      '今日不推播盤中速報與成交量排行',
      `目前報價仍停留在 ${last} 的收盤資料`
    ].join('\n')
  }
}];
